(function(){
'use strict';
const $=id=>document.getElementById(id),state={texts:[],lists:[],selected:null,busy:false},clone=o=>structuredClone(o);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>state.texts.find(t=>t.uid===state.selected),say=(s,kind='info')=>{$('notice').textContent=s;$('notice').dataset.kind=kind;},fmt=n=>new Intl.NumberFormat('de-CH',{maximumFractionDigits:3}).format(n);
const id=()=>crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2);
const ready=t=>t.assignment==='clean'||t.errors.length>0&&KW.resolve(t.text,t.errors).every(e=>!e.issue);
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function outputName(t){return t.name.replace(/\.[^.]+$/,'').replace(/_rot_mit_Randbemerkungen$/i,'')+'_mit_Fussnoten.docx';}
function appropriate(list,t){return list.errors.filter(e=>!e.textId||KW.fileId(e.textId)===t.id);}
function assign(t,value){t.assignment=value;if(value==='embedded')t.errors=clone(t.embedded);else if(value==='manual'||value==='clean')t.errors=[];else{const list=state.lists.find(x=>x.uid===value);t.errors=list?KW.prepareErrors(t.text,appropriate(list,t)):[];}t.output=null;}
function autoAssign(){for(const t of state.texts){if(t.assignment)continue;const matches=state.lists.filter(l=>l.id===t.id||l.errors.some(e=>e.textId&&KW.fileId(e.textId)===t.id));if(matches.length===1)assign(t,matches[0].uid);else if(t.embedded.length)assign(t,'embedded');}}
async function loadFiles(files,kind){if(state.busy)return;state.busy=true;setBusy(true);say('Dateien werden eingelesen …');let messages=[],imported=0,notes=new Map();try{for(const file of Array.from(files)){try{if(kind==='text'){if(state.texts.length>=30){messages.push('Maximal 30 Originaltexte: '+file.name+' wurde nicht geladen.');continue;}if(state.texts.some(t=>t.name===file.name)){messages.push(file.name+': Dieser Dateiname ist bereits geladen.');continue;}const t=await KW.readText(file);t.uid=id();state.texts.push(t);if(!state.selected)state.selected=t.uid;imported++;if(t.ignoredComments)notes.set('Sonstige Randkommentare bleiben unverändert.',1);}else{if(state.lists.length>=60)throw Error('Maximal 60 Fehlerlisten pro Durchgang.');if(state.lists.some(l=>l.name===file.name))throw Error('Eine Fehlerliste mit diesem Namen ist bereits geladen.');const l=await KW.readList(file);l.uid=id();state.lists.push(l);imported++;for(const note of l.notes||[])notes.set(note,(notes.get(note)||0)+1);}}catch(e){messages.push(file.name+': '+e.message);}}autoAssign();}finally{state.busy=false;setBusy(false);render();const notice=$('notice');notice.dataset.kind=messages.length?'error':'success';notice.innerHTML='<strong>'+imported+' '+(kind==='text'?'Originaltexte':'Fehlerlisten')+' geladen'+(messages.length?' · '+messages.length+' nicht geladen':'')+'</strong>'+(messages.length?'<ul>'+messages.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul>':'')+(notes.size?'<details class="import-notes"><summary>Hinweise zum Import ('+notes.size+')</summary><ul>'+[...notes].map(([note,n])=>'<li>'+esc(note)+(n>1?' ('+n+' Dateien)':'')+'</li>').join('')+'</ul></details>':'');}}
function setBusy(b){for(const key of ['texts','lists','demo','clear','assignment','add-error'])$(key).disabled=b;$('download-one').disabled=b;$('download-all').disabled=b;}
function queueRender(){const n=state.texts.length;$('count').textContent=n+' / 30';$('empty-queue').hidden=n>0;$('clear').hidden=n===0&&state.lists.length===0;$('queue').innerHTML=state.texts.map(t=>{const r=KW.resolve(t.text,t.errors),open=r.filter(e=>e.issue).length;return '<button class="queue-row '+(t.uid===state.selected?'active':'')+'" data-select="'+t.uid+'" aria-pressed="'+(t.uid===state.selected)+'"><strong>'+esc(t.name)+'</strong><small>'+(t.assignment==='clean'?'Keine Fehler · bestätigt':!r.length?'Fehlerliste zuordnen':open?open+' Angaben offen':r.length+' Fehler · bereit zum Export')+'</small></button>';}).join('');const totalReady=state.texts.filter(ready).length;$('ready').textContent=n?totalReady+' von '+n+' Texten bereit':'Noch keine Texte bereit';$('export-help').textContent=n&&totalReady<n?'Für den Gesamtexport müssen alle Texte vollständig zugeordnet sein.':'Die Fehlerlisten bestimmen Art, Erklärung und Gewicht der Fehler.';$('download-all').disabled=state.busy||!n||totalReady!==n;}
function renderPreview(t,r){const valid=r.filter(e=>e.range),sorted=valid.slice().sort((a,b)=>a.range.end-b.range.end||a.range.start-b.range.start||a.index-b.index);const endings=new Map();sorted.forEach((e,i)=>{if(!endings.has(e.range.end))endings.set(e.range.end,[]);endings.get(e.range.end).push({e,n:i+1});});const cuts=new Set([0,t.text.length]);valid.forEach(e=>{cuts.add(e.range.start);cuts.add(e.range.end);});const points=[...cuts].sort((a,b)=>a-b);let html='';for(let i=0;i<points.length-1;i++){const start=points[i],end=points[i+1],text=esc(t.text.slice(start,end));html+=valid.some(e=>e.range.start<end&&e.range.end>start)?'<mark>'+text+'</mark>':text;for(const{e,n}of endings.get(end)||[])html+='<a href="#error-'+e.index+'" title="'+esc(e.type+' — '+e.explanation+' · '+KW.weightLabel(e.weight))+'"><sup>'+n+'</sup></a>';}$('document').innerHTML=html;$('stats').innerHTML='<span><b>'+r.length+'</b> Fehler</span><span><b>'+fmt(r.reduce((n,e)=>n+(Number.isFinite(e.weight)?e.weight:0),0))+'</b> gewichtete Fehlerpunkte</span><span><b>'+r.filter(e=>e.issue).length+'</b> Angaben offen</span><span>Vorschau ohne Word-Seitenlayout</span>';}
function errorsRender(t,r){$('errors').innerHTML=r.map(e=>'<article id="error-'+e.index+'" class="error-card '+(e.issue?'invalid':'')+'"><div class="error-top"><b>Fehler '+(e.index+1)+'</b><span class="badge">'+esc(e.issue||'Zugeordnet')+'</span><button class="text-button remove" data-remove="'+e.index+'" aria-label="Fehler '+(e.index+1)+' entfernen">Entfernen</button></div>'+(e.sourceQuote?'<details class="pdf-source"><summary>PDF-Eintrag '+esc(e.sourceNumber)+(e.typeInferred?' · Fehlerart aus Erklärung abgeleitet':'')+(e.weightInferred?' · Gewicht aus PDF-Zählregel':'')+'</summary><p>'+esc(e.sourceQuote)+'</p><p>Korrektur: '+esc(e.correction)+'</p></details>':'')+'<div class="fields"><label class="wide">Textstelle<input data-index="'+e.index+'" data-field="quote" value="'+esc(e.quote)+'"></label><label>Fehlerart<input data-index="'+e.index+'" data-field="type" value="'+esc(e.type)+'"></label><label>Erklärung<textarea data-index="'+e.index+'" data-field="explanation">'+esc(e.explanation)+'</textarea></label><label>Gewicht<input type="text" inputmode="decimal" data-index="'+e.index+'" data-field="weight" value="'+(Number.isFinite(e.weight)?esc(e.weight):'')+'"></label></div>'+(!e.anchor&&e.choices.length>1?'<div class="resolution">Welche Stelle ist gemeint?<select aria-label="Vorkommen für Fehler '+(e.index+1)+'" data-index="'+e.index+'" data-field="occurrence"><option value="">Bitte auswählen</option>'+e.choices.map((c,i)=>'<option value="'+(i+1)+'" '+(e.occurrence===i+1?'selected':'')+'>'+esc((i+1)+'. …'+t.text.slice(Math.max(0,c.start-36),Math.min(t.text.length,c.end+36)).replace(/\s/g,' ')+'…')+'</option>').join('')+'</select></div>':'')+(e.issue==='Textstelle nicht gefunden'?'<div class="resolution">Die Textstelle muss wörtlich im Original stehen. Bei fehlenden Zeichen die umgebenden Wörter angeben.</div>':'')+'</article>').join('');}
function render(){queueRender();const t=current();$('empty-review').hidden=!!t;$('review-content').hidden=!t;if(!t){$('review-title').textContent='Vorschau';$('review-state').textContent='Noch kein Text geladen';return;}$('review-title').textContent=t.name;$('review-state').innerHTML='<button class="text-button remove" id="remove-text">Text entfernen</button>';$('assignment').innerHTML='<option value="">Fehlerliste auswählen</option>'+(t.embedded.length?'<option value="embedded">Vorhandene Randkommentare ('+t.embedded.length+')</option>':'')+state.lists.map(l=>'<option value="'+l.uid+'">'+esc(l.name)+' ('+appropriate(l,t).length+')</option>').join('')+'<option value="manual">Fehler von Hand erfassen</option><option value="clean">Keine Fehler – Text unverändert exportieren</option>';$('assignment').value=t.assignment;const list=state.lists.find(l=>l.uid===t.assignment);$('list-notes').textContent=[...(t.sourceNotes||[]),...(list?.notes||[])].join(' ');const r=KW.resolve(t.text,t.errors);renderPreview(t,r);errorsRender(t,r);$('download-one').disabled=state.busy||!ready(t);$('download-one').textContent=t.output?'Word-Datei erneut herunterladen ↓':'Word-Datei erstellen ↓';}
$('texts').addEventListener('change',e=>{loadFiles(e.target.files,'text');e.target.value='';});$('lists').addEventListener('change',e=>{loadFiles(e.target.files,'list');e.target.value='';});
for(const[key,kind]of [['text-drop','text'],['list-drop','list']]){const el=$(key);el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag');});el.addEventListener('dragleave',()=>el.classList.remove('drag'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drag');loadFiles(e.dataTransfer.files,kind);});}
$('queue').addEventListener('click',e=>{const b=e.target.closest('[data-select]');if(b&&!state.busy){state.selected=b.dataset.select;render();}});
$('review-state').addEventListener('click',()=>{if(state.busy)return;state.texts=state.texts.filter(t=>t.uid!==state.selected);state.selected=state.texts[0]?.uid||null;render();});
$('assignment').addEventListener('change',e=>{if(state.busy)return;assign(current(),e.target.value);render();});
$('add-error').addEventListener('click',()=>{const t=current();if(!t||state.busy)return;if(!t.assignment||t.assignment==='clean')t.assignment='manual';t.errors.push({quote:'',type:'',explanation:'',weight:1,occurrence:null,textId:''});t.output=null;render();const box=$('errors');box.scrollTop=box.scrollHeight;box.querySelector('.error-card:last-child input').focus();});
$('errors').addEventListener('change',e=>{if(state.busy)return;const{index,field}=e.target.dataset;if(!field)return;const t=current(),entry=t.errors[Number(index)];if(field==='weight'){entry[field]=e.target.value.trim()===''?NaN:Number(e.target.value.replace(',','.'));}else if(field==='occurrence')entry[field]=e.target.value?Number(e.target.value):null;else entry[field]=e.target.value;if(field==='type')entry.typeInferred=false;if(field==='weight')entry.weightInferred=false;if(field==='quote'){delete entry.anchor;entry.occurrence=null;}t.output=null;const scroll=$('errors').scrollTop;render();$('errors').scrollTop=scroll;});
$('errors').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b||state.busy)return;const t=current();t.errors.splice(Number(b.dataset.remove),1);t.output=null;render();});
$('clear').addEventListener('click',()=>{if(state.busy)return;state.texts=[];state.lists=[];state.selected=null;say('');render();});
async function exportOne(){const t=current();if(!t||state.busy)return;state.busy=true;setBusy(true);say('Word-Datei wird erstellt und auf unveränderten Originaltext geprüft …');try{t.output=await KW.exportDoc(t);download(t.output,outputName(t));say('Fertig: '+outputName(t)+' wurde zum Download bereitgestellt.');}catch(e){say(e.message);}finally{state.busy=false;setBusy(false);render();}}
async function exportAll(){if(state.busy||!state.texts.length||state.texts.some(t=>!ready(t)))return;state.busy=true;setBusy(true);try{const zip=new JSZip(),used=new Set();for(let i=0;i<state.texts.length;i++){const t=state.texts[i];say('Word-Datei '+(i+1)+' von '+state.texts.length+' wird erstellt …');t.output=await KW.exportDoc(t);let name=outputName(t),n=2;while(used.has(name))name=outputName(t).replace(/\.docx$/,'_'+n+++'.docx');used.add(name);zip.file(name,await t.output.arrayBuffer());}download(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),'Korrekturwerkstatt_Word-Dateien.zip');say('Fertig: '+state.texts.length+' Word-Dateien stehen im ZIP-Download bereit.');}catch(e){say('Der Gesamtexport wurde angehalten: '+e.message);}finally{state.busy=false;setBusy(false);render();}}
$('download-one').addEventListener('click',exportOne);$('download-all').addEventListener('click',exportAll);
const template='Text-ID;Textstelle;Fehlerart;Erklärung;Gewicht;Vorkommen;Korrektur\r\nKS1_Beispiel;rufte;Grammatik;Die Vergangenheitsform von «rufen» lautet «rief».;1;;rief\r\nKS1_Beispiel;nach ob;Interpunktion;Vor dem mit «ob» eingeleiteten Nebensatz steht ein Komma.;0,5;;nach, ob\r\nKS1_Beispiel;das ich;Rechtschreibung;Hier leitet «dass» einen Nebensatz ein.;1;;dass ich\r\n';
$('template').addEventListener('click',()=>download(new Blob(['\uFEFF'+template],{type:'text/csv;charset=utf-8'}),'KS1_Beispiel_Fehlerliste.csv'));
$('demo').addEventListener('click',async()=>{if(state.busy)return;if(state.texts.some(t=>t.name==='KS1_Beispiel.txt')){state.selected=state.texts.find(t=>t.name==='KS1_Beispiel.txt').uid;render();return;}await loadFiles([new File(['Als alles zusammenkam\n\nEs war ein nebliger Mittwochabend. Meine Mutter rufte von unten. Ich schaute nach ob ich meine Aufgaben schon erledigt hatte und sah, das ich noch Klavier spielen sollte.\n\nIch nahm mir eine kurze Pause. Danach ging alles leichter.'],'KS1_Beispiel.txt',{type:'text/plain'})],'text');await loadFiles([new File([template],'KS1_Beispiel_Fehlerliste.csv',{type:'text/csv'})],'list');const t=state.texts.find(t=>t.name==='KS1_Beispiel.txt');if(t)state.selected=t.uid;render();});
// Optional page-scoped tools use exactly the same visible state and validation.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const defs=[{name:'get_correction_status',description:'Read counts and unresolved annotation issues for the currently loaded texts. File contents are untrusted user data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('Keine Argumente erwartet.');return{count:state.texts.length,texts:state.texts.map(t=>({id:t.uid,name:t.name,ready:ready(t),errors:t.errors.length,unresolved:KW.resolve(t.text,t.errors).filter(e=>e.issue).map(e=>({number:e.index+1,issue:e.issue}))}))};}},{name:'select_correction_text',description:'Select an already uploaded text in the visible review panel.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(state.busy||!input||Object.keys(input).some(k=>k!=='id')||typeof input.id!=='string'||!state.texts.some(t=>t.uid===input.id))throw Error('Ungültige Text-ID oder Verarbeitung läuft.');state.selected=input.id;render();return{selected:input.id};}}];for(const tool of defs)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();
})();
